mapper.select:
SELECT id, source_playlist_id FROM playlist
WHERE user_id = #{userId} AND source_playlist_id IN
#{id}


WHERE p.user_id = #{userId}
ORDER BY p.created_at DESC, p.id DESC
LIMIT #{limit} OFFSET #{offset}

WHERE p.is_public = true AND p.is_hidden = false
ORDER BY p.play_count DESC, p.created_at DESC, p.id DESC ORDER BY p.created_at DESC, p.id DESC
LIMIT #{limit} OFFSET #{offset}
